// Guild rank is independent of character level. Promotion is earned in combat.
const GUILD_STORY=[
 '灯火の村へ辿り着いたあなたは、ギルドに冒険者として登録した。まずは草原の群れを退け、村への道を取り戻そう。',
 '草原の奥で見つかった燐光石は、洞窟の異変を示していた。坑道へ向かった調査隊を追おう。',
 '坑道の古文書は、森の根を流れる黒い力を伝えている。森の住民の依頼に応えよう。',
 '森を蝕む水源は湿地にある。毒を撒く魔物を狩り、腐水の司祭を探す。',
 '清めた水に映ったのは砂漠の古王朝。隊商を守り、砂に埋もれた門を探そう。',
 '砂漠の門は雪原へ通じていた。永遠の吹雪を越え、失われた遠征隊の足跡を辿る。',
 '遠征隊の旗が示す先は雷鳴の高原。天空の槍を越え、裂け目の鍵を集める。',
 '雷の鍵は火山の炉で目覚める。熔王に立ち向かい、門を閉じる武器の製法を得よう。',
 '残る製法は海に沈んだ都市に眠る。海岸の魔物を払い、幽霊船長の記憶を追う。',
 '都市の記憶が古代遺跡への道を開いた。遺跡の守護者は、終焉王の帰還を告げる。',
 '最後の鍵は黄昏の墓地。かつて門を封じた冒険者たちの魂を解放しよう。',
 '終焉の裂け目が開いた。村で出会った人々の願いを背負い、終焉王アザレクを討て。'
];
for(let r of REGIONS){let s={id:'r'+r.id+'s0',name:'裏境の'+r.bosses[3].name,region:r.id,role:7,boss:true,secret:true,index:3};SPECIES[s.id]=s;r.secret=s;for(let [i,t]of MATERIAL_TIERS.entries())MATERIALS[s.id+':'+i]={id:s.id+':'+i,species:s.id,tier:i,name:s.name+'の'+t.part,color:t.color}}
const guildCampaignBase=campaign;campaign=()=>{let c=guildCampaignBase();c.rankXP??=0;c.questDone??=[];return c};
function promotionXP(rank){return 180+rank*60}
function guildQuest(id){let match=/^(hunt|boss|trial|secret):(.+)$/.exec(id);if(!match)return null;let kind=match[1],spec=SPECIES[match[2]];if(!spec||spec.exRank||kind==='boss'&&spec.secret||kind==='hunt'&&spec.boss||kind!=='hunt'&&!spec.boss||kind==='secret'&&!spec.secret||kind==='trial'&&(spec.index!==3||spec.secret))return null;return{id,kind,target:spec.id,region:spec.region,required:kind==='hunt'?8+spec.role%3*2:1,xp:kind==='hunt'?60+spec.region*5:kind==='secret'?150:100+spec.region*8,name:kind==='hunt'?spec.name+'の討伐':kind==='trial'?'ランク'+(spec.region+2)+'昇格試験':kind==='secret'?'裏ボス挑戦：'+spec.name:spec.name+'の討伐'}}
function guildQuestAllowed(q){let c=campaign();if(!q||q.region>c.unlocked)return false;if(!c.questDone.length)return q.id==='hunt:r0e0';if(q.kind==='secret')return c.unlocked>q.region;if(q.kind==='trial')return q.region===c.unlocked&&q.region<11&&c.rankXP>=promotionXP(c.unlocked+1);return true}
function acceptGuildQuest(id){let q=guildQuest(id),c=campaign();if(!villageOpen||c.contract||!guildQuestAllowed(q))return false;if(!worldTransaction(()=>c.contract={target:q.target,kind:q.kind,id:q.id,required:q.required,progress:0,killed:false}))return false;showVillage(q.region);return true}
acceptContract=id=>acceptGuildQuest('boss:'+id);
claimContract=()=>{let c=campaign(),q=c.contract;if(!villageOpen||!q?.killed)return false;let spec=SPECIES[q.target],quest=guildQuest(q.id||'boss:'+q.target);if(!quest)return false;
 if(!worldTransaction(()=>{if(!c.questDone.includes(quest.id)){c.questDone.push(quest.id);p.points+=quest.kind==='hunt'?1:2}if(spec.boss&&!c.completed.includes(spec.id))c.completed.push(spec.id);p.gold+=80+spec.region*50;c.rankXP+=quest.xp;if(quest.kind==='trial'&&spec.region===c.unlocked){c.rankXP-=promotionXP(c.unlocked+1);c.unlocked=Math.min(11,c.unlocked+1)}c.contract=null}))return false;showVillage();return true;
};
endgameUnlocked=()=>campaign().completed.includes('r11b3');
const guildValidateBase=validateSave;validateSave=data=>{let result=guildValidateBase(data),src=data.p.campaign;if(!src)return result;let c=result.p.campaign;c.rankXP=src.rankXP===undefined?0:saveNumber(src.rankXP,'ランク経験値',0,1e9);if(!Number.isInteger(c.rankXP))throw Error('ランク経験値が不正です');c.questDone=src.questDone||[];if(!Array.isArray(c.questDone)||c.questDone.length>200||c.questDone.some(id=>!guildQuest(id))||new Set(c.questDone).size!==c.questDone.length)throw Error('依頼履歴が不正です');c.questDone=[...c.questDone];for(let rank=0;rank<Math.min(9,c.unlocked);rank++)if(!c.questDone.includes('trial:r'+rank+'b3'))throw Error('昇格試験が未達成です');if(src.contract){let old=src.contract,q=guildQuest(old.id||'boss:'+old.target);if(!q||q.target!==old.target)throw Error('依頼内容が不正です');let progress=old.progress??(old.killed?q.required:0);if(!Number.isInteger(progress)||progress<0||progress>q.required||old.killed!==(progress>=q.required))throw Error('討伐数が不正です');c.contract={target:q.target,id:q.id,kind:q.kind,required:q.required,progress,killed:old.killed}}return result};
const guildSpawnBase=spawnSpecies;spawnSpecies=(spec,x,y)=>{let e=guildSpawnBase(spec,x,y);if(e){let q=campaign().contract;if(spec.secret){e.hp*=2.5;e.max=e.hp;e.secret=true}else if(q?.kind==='trial'&&q.target===spec.id){e.hp*=1.5;e.max=e.hp;e.trial=true}}return e};
const guildLoadBase=loadWorld;loadWorld=()=>{guildLoadBase();let q=campaign().contract;if(!villageOpen&&q?.kind==='secret'&&SPECIES[q.target].region===worldRegion){let a=BOSS_ARENAS[3],pos=center(a.cx,a.cy);enemies=enemies.filter(e=>e.species!==REGIONS[worldRegion].bosses[3].id);spawnSpecies(SPECIES[q.target],pos.x,pos.y)}};
showVillage=(region=campaign().region)=>{let c=campaign(),r=REGIONS[region]||REGIONS[0],q=c.contract,quest=q&&guildQuest(q.id||'boss:'+q.target),first=!c.questDone.length;let quests=first?[guildQuest('hunt:r0e0')]:[...r.enemies.map(e=>guildQuest('hunt:'+e.id)),...r.bosses.map(e=>guildQuest('boss:'+e.id))];if(guildQuestAllowed(guildQuest('secret:'+r.secret.id)))quests.push(guildQuest('secret:'+r.secret.id));if(r.id===c.unlocked&&r.id<9&&!first)quests.unshift(guildQuest('trial:'+r.bosses[3].id));
 worldMenu('冒険者ギルド · ランク '+(c.unlocked+1),'<div class="world-tabs"><button onclick="showForge()">素材工房</button><button onclick="showDps()">DPS訓練</button><button onclick="panel(\'inventory\')">装備</button></div><p class="guild-story">'+GUILD_STORY[r.id]+'</p><p>ランク経験値 '+c.rankXP+' / '+(c.unlocked<11?promotionXP(c.unlocked+1):'最高ランク')+'</p>'+(quest?'<div class="contract-active">'+quest.name+' · '+q.progress+' / '+q.required+(q.killed?' <button onclick="claimContract()">報告して報酬を受け取る</button>':'')+' <button onclick="cancelContract()">取り消す</button></div>':'')+'<label>地域<select aria-label="探索地域" onchange="showVillage(+this.value)">'+REGIONS.map(x=>'<option value="'+x.id+'" '+(x.id===r.id?'selected':'')+' '+(x.id>c.unlocked?'disabled':'')+'>R'+(x.id+1)+' '+x.name+'</option>').join('')+'</select></label><div class="guild-quests">'+quests.map(t=>'<button onclick="acceptGuildQuest(\''+t.id+'\')" '+(q||!guildQuestAllowed(t)?'disabled':'')+'>'+t.name+'<small>'+t.required+'体 · ランクXP '+t.xp+(t.kind==='trial'?' · 必要XP '+promotionXP(c.unlocked+1):'')+(c.questDone.includes(t.id)?' · 再受注可':'')+'</small></button>').join('')+'</div><button onclick="departRegion('+r.id+')" '+(r.id>c.unlocked?'disabled':'')+'>'+r.name+'へ出発</button><details><summary>冒険者の手引き</summary><p>指定された敵だけが討伐数に数えられます。討伐後は村で報告してランク経験値を獲得。昇格試験のボスを倒して報告すると、次の地域と前地域の裏ボス依頼が解放されます。敵の素材はF／Bで回収し工房で製作。並64%・良25%・希少9%・伝説2%。昇格試験はランク10まで。その後は経験値でランク100へ。10ランクごとにEX依頼が解放され、EX100の削り報酬でも終焉装備を製作できます。</p></details>');
};
const guildHudBase=drawHud;drawHud=()=>{guildHudBase();if(!p?.campaign)return;let c=campaign(),q=c.contract;if(!villageOpen&&q){let quest=guildQuest(q.id||'boss:'+q.target);hudText($('objective'),quest.name);hudText($('progress'),fieldQuestStatus().progress)}};
